package com.example.examplemod.community;
import com.example.examplemod.city.*;
import com.example.examplemod.network.*;
import com.example.examplemod.auth.PlayerNames;
import com.example.examplemod.economy.EconomyManager;
import com.example.examplemod.projects.*;
import net.minecraft.nbt.*;
import net.minecraft.server.level.ServerPlayer;
import net.neoforged.neoforge.network.PacketDistributor;
import java.util.*;
public final class CommunityService {
    private CommunityService(){}
    private static final Map<UUID,long[]> windows=new HashMap<>();
    /** Legacy invitations without a recorded timestamp remain usable; no fictional expiry dates. */
    public static void reconcileInvites(net.minecraft.server.MinecraftServer s,UUID owner){
        var manager=CityManager.get(s.overworld());var inbox=CommunityInbox.get(s);var notices=CommunityData.get(s);
        for(var city:manager.getCities()){var invite=city.getInvite(owner);if(invite==null)continue;
            var event=inbox.history(owner).stream().filter(e->e.id().equals(invite.token())).findFirst().orElse(null);
            boolean expired=event!=null&&System.currentTimeMillis()-event.time()>7L*24*60*60*1000;
            boolean invalid=manager.getMemberCity(owner)!=null||invite.getInvokerId()!=null&&!city.isAdmin(invite.getInvokerId());
            if(expired||invalid){city.removeInvite(owner);manager.setDirty();inbox.resolve(owner,invite.token(),expired?"city_invite_expired":"city_invite_unavailable");notices.outbox.removeIf(n->invite.token().equals(n.token()));notices.setDirty();}
        }
        for(var event:inbox.history(owner))if(event.kind().equals("city_invite")&&event.city()!=null){var city=manager.getCity(event.city());var invite=city==null?null:city.getInvite(owner);if(invite==null||!invite.token().equals(event.id())){inbox.resolve(owner,event.id(),"city_invite_unavailable");notices.outbox.removeIf(n->event.id().equals(n.token()));notices.setDirty();}}
    }
    public static String respond(net.minecraft.server.MinecraftServer s,UUID actor,UUID cityId,UUID token,boolean accept){
        reconcileInvites(s,actor);var manager=CityManager.get(s.overworld());var city=manager.getCity(cityId);if(city==null)return "unknown";var invite=city.getInvite(actor);
        if(invite==null||token==null||!invite.token().equals(token))return "stale";
        if(invite.getInvokerId()!=null&&!city.isAdmin(invite.getInvokerId()))return "permission";
        if(accept&&manager.getMemberCity(actor)!=null)return "membership";
        CommunityInbox.get(s).resolve(actor,invite.token(),accept?"city_invite_accepted":"city_invite_declined");if(accept)city.acceptInvite(actor);else city.removeInvite(actor);manager.setDirty();
        CityInviteDirectory.reportOutcome(s,invite.getInvokerId(),PlayerNames.name(s,actor),city.getName(),accept);CityInviteDirectory.publishMembers(s,city);
        CommunityData.get(s).audit(cityId,actor,null,accept?"joined":"declined");if(invite.getInvokerId()!=null)CommunityInbox.get(s).add(invite.getInvokerId(),invite.token(),accept?"city_joined":"city_declined",actor,cityId,null,city.getName(),System.currentTimeMillis());return "ok";
    }
    public static String invite(net.minecraft.server.MinecraftServer s,UUID actor,UUID target,UUID cityId){
        var m=CityManager.get(s.overworld());var c=m.getCity(cityId);if(c==null||!c.isAdmin(actor))return "permission";if(target==null||m.getMemberCity(target)!=null)return "membership";
        if(c.getInvites().size()>=64)return "full";
        if(s.getPlayerList().getPlayer(target)==null&&!com.example.examplemod.profile.ProfileSavedData.get(s).contains(target)
                &&(s.getProfileCache()==null||s.getProfileCache().get(target).isEmpty())&&!java.nio.file.Files.isRegularFile(s.getWorldPath(net.minecraft.world.level.storage.LevelResource.PLAYER_DATA_DIR).resolve(target+".dat")))return "unknown";
        var result=c.addInvite(target,actor);if(result==City.InviteResult.ALREADY_INVITED)return "ok";if(result!=City.InviteResult.SENT)return "state";
        m.setDirty();CommunityInbox.get(s).add(target,c.getInvite(target).token(),"city_invite",actor,c.getId(),null,c.getName(),System.currentTimeMillis());var peer=s.getPlayerList().getPlayer(target);if(peer!=null)PacketDistributor.sendToPlayer(peer,new CityInviteNotificationPayload(c.getPylonPos(),c.getName(),PlayerNames.name(s,actor)));
        CommunityData.get(s).audit(c.getId(),actor,target,"invited");CommunityData.get(s).enqueue(target,actor,"INVITE",c.getName(),peer!=null,c.getId(),c.getInvite(target).token());return "ok";
    }
    public static void handle(ServerPlayer p,CommunityRequestPayload r){if(p instanceof net.neoforged.neoforge.common.util.FakePlayer)return;
        long now=net.minecraft.Util.getMillis();windows.entrySet().removeIf(e->now-e.getValue()[0]>60000);var w=windows.computeIfAbsent(p.getUUID(),id->new long[]{now,0});if(now-w[0]>1000){w[0]=now;w[1]=0;}
        var out=new CompoundTag();out.putUUID("Request",r.request());if(++w[1]>6){out.putString("Result","busy");PacketDistributor.sendToPlayer(p,new CommunityStatePayload(out));return;}
        var s=p.getServer();reconcileInvites(s,p.getUUID());var manager=CityManager.get(s.overworld());var own=manager.getMemberCity(p.getUUID());var data=CommunityData.get(s);var c=r.city()==null?own:manager.getCity(r.city());String result="ok";
        if(r.action()==CommunityRequestPayload.Action.SUMMARY||r.action()==CommunityRequestPayload.Action.INBOX){PacketDistributor.sendToPlayer(p,new CommunityStatePayload(CommunitySummary.build(p,out,r.action()==CommunityRequestPayload.Action.INBOX,r.page())));return;}
        if(r.action()==CommunityRequestPayload.Action.READ_ALLIANCE){out.putBoolean("ReadAck",true);var alliances=com.example.examplemod.alliance.AllianceSavedData.get(s).book;var selected=r.target()==null?null:alliances.get(r.target());boolean member=selected!=null&&own!=null&&selected.cities.contains(own.getId());if(member&&r.token()!=null&&selected.chat.stream().anyMatch(m->m.id().equals(r.token()))){CommunityInbox.get(s).readAllianceThrough(p.getUUID(),selected.id,r.token(),selected.chat.stream().map(com.example.examplemod.alliance.AllianceBook.Message::id).toList());out.putString("Result","ok");}else out.putString("Result","stale");PacketDistributor.sendToPlayer(p,new CommunityStatePayload(out));return;}
        switch(r.action()){
            case VIEW,INBOX,RELATIONS,SUMMARY -> {}
            case SET_TRUST,SET_TERRITORY -> {if(c==null||own!=c||!c.isAdmin(p.getUUID())||!CityMembershipService.atPylon(p,c)||r.target()==null||manager.getCity(r.target())==null||r.target().equals(c.getId())||r.value()<0||r.value()>1)result="permission";else if(r.action()==CommunityRequestPayload.Action.SET_TRUST)manager.setTrusted(c.getId(),r.target(),r.value()==1);else manager.setTerritoryAccess(c.getId(),r.target(),p.getUUID(),r.value()==1);}
            case READ_ALLIANCE -> {}
            case READ_INBOX -> CommunityInbox.get(s).read(p.getUUID(),r.token());
            case LEAVE,KICK,TRANSFER -> result=CityMembershipService.change(p,CityMembershipService.Action.valueOf(r.action().name()),r.city(),r.target(),r.request());
            case ACCEPT,DECLINE -> result=r.city()==null?"unknown":respond(s,p.getUUID(),r.city(),r.token(),r.action()==CommunityRequestPayload.Action.ACCEPT);
            case INVITE -> result=c==null?"permission":invite(s,p.getUUID(),r.target(),c.getId());
            case REVOKE -> {if(c==null||!c.isAdmin(p.getUUID()))result="permission";else {var i=c.getInvite(r.target());if(i==null||!i.token().equals(r.token()))result="stale";else {c.removeInvite(r.target());CommunityInbox.get(s).resolve(r.target(),i.token(),"city_invite_revoked");data.outbox.removeIf(n->i.token().equals(n.token()));data.setDirty();manager.setDirty();data.audit(c.getId(),p.getUUID(),r.target(),"revoked");}}}
            case ROLE -> {var roles=CityMember.Role.values();if(c==null||r.value()<0||r.value()>=roles.length||!CityAuthority.assign(c,p.getUUID(),r.target(),roles[r.value()]))result="permission";else{c.setMemberRole(r.target(),roles[r.value()]);manager.setDirty();CityInviteDirectory.publishMembers(s,c);data.audit(c.getId(),p.getUUID(),r.target(),"role:"+roles[r.value()].name());}}
            case PREFERENCE -> {var q=data.preferences(p.getUUID());var v=switch(r.value()){case 0->new CommunityData.Preferences(!q.telegram(),q.preview(),q.offlineOnly(),q.quiet(),q.offset());case 1->new CommunityData.Preferences(q.telegram(),!q.preview(),q.offlineOnly(),q.quiet(),q.offset());case 2->new CommunityData.Preferences(q.telegram(),q.preview(),!q.offlineOnly(),q.quiet(),q.offset());case 3->new CommunityData.Preferences(q.telegram(),q.preview(),q.offlineOnly(),!q.quiet(),q.offset());default->q;};data.preferences.put(p.getUUID(),v);data.setDirty();}
            case MUTE -> {if(r.target()!=null){var set=data.muted.computeIfAbsent(p.getUUID(),id->new HashSet<>());if(r.value()==1&&set.size()<128){set.add(r.target());data.outbox.removeIf(n->n.owner().equals(p.getUUID())&&n.peer().equals(r.target()));}else if(r.value()==0)set.remove(r.target());data.preferences.putIfAbsent(p.getUUID(),data.preferences(p.getUUID()));data.setDirty();}}
        }
        out.put("Inbox",CommunityInbox.get(s).page(p.getUUID(),r.action()==CommunityRequestPayload.Action.INBOX?Math.min(1,r.page()):0));out.putInt("InboxTotal",CommunityInbox.get(s).history(p.getUUID()).size());out.putInt("AllianceUnread",(int)CommunityInbox.get(s).history(p.getUUID()).stream().filter(e->!e.read()&&e.kind().equals("alliance_message")).count());out.putInt("InboxUnread",CommunityInbox.get(s).unread(p.getUUID()));
        var counts=CommunitySummary.build(p,new CompoundTag(),false,0);for(String key:List.of("Unread","AllianceUnread","InboxUnread"))out.putInt(key,counts.getInt(key));
        out.putString("SelfName",PlayerNames.name(p));own=manager.getMemberCity(p.getUUID());out.putString("OwnRole",own==null?"":own.getMember(p.getUUID()).getRole().name());out.putString("Result",result);if(own!=null){out.putUUID("OwnCity",own.getId());out.putString("OwnName",own.getName());out.putString("OwnRole",own.getMember(p.getUUID()).getRole().name());}
        out.putBoolean("PylonAccess",CityMembershipService.atPylon(p,c));
        if(r.target()!=null&&c!=null){var chosen=c.getMember(r.target());if(chosen!=null){out.putUUID("Selected",r.target());out.putString("SelectedName",PlayerNames.name(s,r.target()));out.putBoolean("CanKick",CityMembershipService.mayKick(c,p.getUUID(),r.target())&&CityMembershipService.atPylon(p,c));out.putBoolean("CanTransfer",CityMembershipService.mayTransfer(c,p.getUUID(),r.target())&&CityMembershipService.atPylon(p,c));}}
        if(own!=null){final UUID ownId=own.getId();var alliances=com.example.examplemod.alliance.AllianceSavedData.get(s).book;var alliance=alliances.city(own.getId());if(alliance!=null){out.putUUID("AllianceId",alliance.id);out.putString("AllianceName",alliance.name);var ref=new com.example.examplemod.alliance.AllianceBook.CityRef(own.getId(),own.getName(),own.getOwner(),own.getMembers().stream().map(CityMember::getPlayerId).collect(java.util.stream.Collectors.toSet()));if(alliances.council(alliance,ref,p.getUUID()))out.putInt("CouncilVotes",(int)alliance.proposals.values().stream().filter(v->v.expires>System.currentTimeMillis()&&v.electorate.contains(ownId)&&!v.votes.containsKey(ownId)).count());}out.putInt("AllianceInvites",(int)alliances.all().stream().filter(a->a.invitations.getOrDefault(ownId,0L)>System.currentTimeMillis()).count());}
        var social=com.example.examplemod.social.SocialSavedData.get(s).book;out.putInt("FriendRequests",(int)social.requests.stream().filter(e->e.to().equals(p.getUUID())).count());out.putInt("Unread",counts.getInt("Unread"));
        var cities=manager.getCities().stream().filter(v->v.getName().toLowerCase(Locale.ROOT).contains(r.query().toLowerCase(Locale.ROOT))).sorted(Comparator.comparing(City::getName).thenComparing(City::getId)).toList();int page=Math.min(r.page(),Math.max(0,(cities.size()-1)/12));out.putInt("Page",page);out.putInt("Total",cities.size());var rows=new ListTag();for(var v:cities.subList(page*12,Math.min(cities.size(),page*12+12))){var t=new CompoundTag();t.putUUID("Id",v.getId());t.putString("Name",v.getName());t.putInt("Members",v.getMemberCount());t.putInt("Level",v.getLevel());t.putInt("Color",v.getColorRgb());rows.add(t);}out.put("Cities",rows);
        if(c!=null){out.putUUID("City",c.getId());out.putString("Name",c.getName());out.putString("Description",c.getIdentity().description());out.putBoolean("Manage",c.isAdmin(p.getUUID()));out.putBoolean("Owner",c.isOwner(p.getUUID()));var members=new ListTag();int memberPage=Math.min(Math.max(0,r.action()==CommunityRequestPayload.Action.VIEW?r.value():0),Math.max(0,(c.getMemberCount()-1)/16));out.putInt("MemberPage",memberPage);out.putInt("MemberTotal",c.getMemberCount());var sorted=c.getMembers().stream().sorted(Comparator.comparing(m->PlayerNames.name(s,m.getPlayerId()))).toList();for(var member:sorted.subList(memberPage*16,Math.min(sorted.size(),memberPage*16+16))){var t=new CompoundTag();t.putUUID("Id",member.getPlayerId());t.putString("Name",PlayerNames.name(s,member.getPlayerId()));t.putString("Role",member.getRole().name());t.putBoolean("Online",s.getPlayerList().getPlayer(member.getPlayerId())!=null);t.putBoolean("Assignable",c.isAdmin(p.getUUID())&&!c.isOwner(member.getPlayerId())&&!p.getUUID().equals(member.getPlayerId())&&(c.isOwner(p.getUUID())||!c.isAdmin(member.getPlayerId())));members.add(t);}out.put("Members",members);}
        var invites=new ListTag();for(var v:manager.getCities())for(var i:v.getInvites())if(invites.size()<64&&(i.getPlayerId().equals(p.getUUID())||v.isAdmin(p.getUUID()))){var t=new CompoundTag();t.putUUID("City",v.getId());t.putString("Name",v.getName());t.putUUID("Target",i.getPlayerId());t.putString("Player",PlayerNames.name(s,i.getPlayerId()));t.putUUID("Token",i.token());t.putBoolean("Incoming",i.getPlayerId().equals(p.getUUID()));if(i.getInvokerId()!=null){t.putString("Inviter",PlayerNames.name(s,i.getInvokerId()));var role=CityAuthority.role(v,i.getInvokerId());t.putString("Role",role==null?"":role.name());}invites.add(t);}out.put("Invites",invites);
        var projects=new ListTag();if(own!=null)for(var project:EconomyManager.get(s.overworld()).projects().all())if(projects.size()<12&&Objects.equals(project.city(),own.getId())&&(project.status()==Project.Status.REVIEW||project.status()==Project.Status.PENDING_FUNDING)&&!CommunityActions.attention(project,com.example.examplemod.projects.ProjectNetworkHandlers.actor(p,manager,own)).isBlank()){var t=new CompoundTag();t.putUUID("Id",project.id());t.putString("Title",project.title());t.putString("Status",project.status().name());projects.add(t);}out.put("Projects",projects);
        if(c!=null&&own==c){final UUID cityId=c.getId();var otherCities=manager.getCities().stream().filter(v->!v.getId().equals(cityId)).sorted(Comparator.comparing(City::getName)).toList();int relationsPage=Math.min(r.page(),Math.max(0,(otherCities.size()-1)/16));out.putInt("RelationsPage",relationsPage);out.putInt("RelationsTotal",otherCities.size());var rowsRelations=new ListTag();for(var other:otherCities.subList(relationsPage*16,Math.min(otherCities.size(),relationsPage*16+16))){var t=new CompoundTag();t.putUUID("Id",other.getId());t.putString("Name",other.getName());boolean ours=manager.trusts(cityId,other.getId()),theirs=manager.trusts(other.getId(),cityId);t.putString("Status",ours&&theirs?"partner":ours?"trusted":theirs?"trusts_us":"none");t.putBoolean("Trust",ours);t.putBoolean("Access",manager.grantsTerritoryAccess(cityId,other.getId()));t.putBoolean("IncomingAccess",manager.grantsTerritoryAccess(other.getId(),cityId));rowsRelations.add(t);}out.put("Relations",rowsRelations);}
        if(r.target()!=null){out.putUUID("MutedPeer",r.target());out.putBoolean("Muted",data.muted(p.getUUID(),r.target()));}
        var prefs=data.preferences(p.getUUID());out.putBoolean("Telegram",prefs.telegram());out.putBoolean("Preview",prefs.preview());out.putBoolean("OfflineOnly",prefs.offlineOnly());out.putBoolean("Quiet",prefs.quiet());PacketDistributor.sendToPlayer(p,new CommunityStatePayload(out));
    }
}
